from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT=Path(r'C:\anc')
OUT=ROOT/'output'/'documents'/'TeamAt_VoxShield_Complete_Video_Script.docx'
OUT.parent.mkdir(parents=True,exist_ok=True)
d=Document()
s=d.sections[0]
s.page_width=Inches(8.5); s.page_height=Inches(11)
s.top_margin=s.bottom_margin=Inches(.65)
s.left_margin=s.right_margin=Inches(.75)
for name in ['Normal','Title','Subtitle','Heading 1','Heading 2','Heading 3']:
 st=d.styles[name]; st.font.name='Calibri'; st.font.color.rgb=RGBColor(0,0,0)
 st.paragraph_format.space_after=Pt(5)
 st.paragraph_format.line_spacing=1.04
d.styles['Normal'].font.size=Pt(10.5)
d.styles['Title'].font.size=Pt(27)
d.styles['Heading 1'].font.size=Pt(20)
d.styles['Heading 2'].font.size=Pt(14)
for style in d.styles:
 pr=style.element.find(qn('w:pPr'))
 if pr is not None:
  for border in list(pr.findall(qn('w:pBdr'))):pr.remove(border)
f=s.footer.paragraphs[0]; f.text='Team@ | VoxShield filming guide | 1 October 2026 | '
field=OxmlElement('w:fldSimple'); field.set(qn('w:instr'),'PAGE'); f._p.append(field)
for r in f.runs:r.font.size=Pt(8)

def p(text):d.add_paragraph(text)
def h(text):d.add_heading(text,2)
def bullets(items):
 for x in items:d.add_paragraph(x,'List Bullet')
def label(name,text):
 q=d.add_paragraph();q.add_run(name+' ').bold=True;q.add_run(text)
def speech(text):
 q=d.add_paragraph();q.paragraph_format.space_before=Pt(5)
 q.add_run(text).font.size=Pt(12)
def page(title):d.add_page_break();d.add_heading(title,1)

d.add_paragraph('Team@ VoxShield video script','Title')
p('Two speakers in separate locations | Three minute submission edit')
p('Use this as the recording script and the editor\'s guide. Speaker 1 explains the reason for the project, the decisions behind it and the next step. Speaker 2 shows the signal path, live comparison and evidence. Record each short paragraph as a separate take, then use the screen recordings and hardware footage to join the story.')
h('The story the viewer should remember')
p('A command is lost in noise. Team@ introduces itself and VoxShield, explains its first inline audio idea, and follows the engineering choices into a real demonstration. Speaker 2 shows the signal path and evidence, then Speaker 1 returns to connect those results to the next hardware step. The final line returns to the command in the opening.')
h('Timing that allows people to speak naturally')
p('Record the main script at a comfortable pace, allowing roughly 20 seconds for the opening, audible comparison and end card. The three minute timeline below is an editing target. Time the actual rehearsal and use the short cuts on the final page if needed. Replace [Name 1] and [Name 2] with the speakers\' names; pronounce Team@ as “Team at”. Keep any optional longer passages out of the three minute edit.')
bullets(['0:00-0:04: black screen, brief static, hand reveal.','0:04-1:09: Speaker 1 introduces the problem and design journey.','1:09-1:38: Speaker 2 explains the current architecture.','1:38-2:03: continuous live A/B comparison, including listening time.','2:03-2:28: measured results and Pi evidence.','2:28-2:56: Speaker 1 returns with the next step and closing line.','2:56-3:00: end card and QR code.'])
h('How the two locations connect')
p('Both speakers address the viewer. Speaker 1 finishes the introduction looking into the lens; the edit cuts to Speaker 2 already framed beside the laptop. Neither speaker looks off camera as though the other is standing nearby. Use the same subtitle style and similar camera height to connect the locations visually.')

page('Speaker 1 opening and first idea')
label('Shot','Medium shot from roughly waist or chest upward. Camera at eye level. Leave a little empty space on one side for captions. Use a quiet background; the opening noise is added in editing.')
h('The opening reveal')
label('Action','Begin with your palm loosely covering the camera lens. After two seconds of safe static, remove it smoothly and settle into your position. Let your expression register a small interruption, then regain focus. No exaggerated shock or pain.')
label('Delivery','Say the apology conversationally. Pause briefly. Become serious as you explain the consequence. Keep your hands relaxed through the first sentence.')
speech('Sorry about that. Imagine hearing “hold position” through that noise. One missed word can change the instruction.')
label('Edit','Black screen for about two seconds. Reduce the static before the speech starts. Show HOLD POSITION as text, with a brief gap in one word. Label this opening as an illustrative sound sequence if the effect could be confused with a recorded model comparison.')
h('Introduce the people and the project')
label('Delivery','Let the serious opening settle, then become welcoming. Say the team name clearly. A small natural smile is appropriate during your introduction; return to a focused expression for the project purpose.')
speech('Hello, I am [Name 1], and we are Team@. For Smart India Hackathon, we are building VoxShield to help speech remain understandable in noisy defence communication.')
label('Edit','Show Team@ prominently, followed by VoxShield and PS 26052. Put the speaker\'s real name in a small lower third. If a team photo is available, show it briefly under this line. Do not invent team roles or imply all members appear in the video.')
h('Explain why you chose the approach')
label('Expression','Curious and thoughtful. This should sound like you are remembering the first design conversation.')
label('Gesture','Use one small connecting motion with an open hand on “existing communication chain”. Then let your hands rest.')
speech('Our first idea was an inline audio optimizer: a local processing layer inside an existing communication chain, working without internet access.')
label('Edit','Draw a simple microphone to radio to listener chain. Insert a small VoxShield block. Label the drawing PROPOSED INTEGRATION. Keep your voice continuing over the animation.')
h('Explain the actual problem')
label('Delivery','Give each noise example a little space. Emphasize “speech” in the final sentence. Avoid an angry or dramatic tone.')
speech('The challenge was preserving speech through engines, wind and sudden noise bursts, while keeping up with a conversation. Removing noise meant little if we also removed the words.')
label('Edit','Show three short labels: steady noise, changing noise, sudden bursts. Then show SPEECH PRESERVATION beside a clean spoken-word waveform. These graphics explain the requirement; they do not claim measured live performance.')

page('Speaker 1 learning and introduction to the demo')
h('Give the journey a reason')
label('Expression','Reflective and direct. You are explaining an engineering lesson you encountered, with no need to act disappointed.')
label('Delivery','Slow slightly on “changed our approach”. Brief pause before the microphone lesson. If you stumble on a model name, repeat the paragraph rather than rushing it.')
speech('We explored different enhancement models and dual-channel processing. Real microphone tests showed why the whole system matters: microphone placement, device processing and separate clocks all change what reaches the model.')
label('Gesture','A small open-palm gesture on “real microphones” is enough. Keep eye contact with the lens for the lesson; do not point repeatedly at captions.')
label('Edit','Use actual project footage: an early architecture sketch, a training console, then the JBL and laptop microphone setup. Optional small timeline labels can name GTCRN, UL-UNAS and the current deep-filter model only where the project records support them. Do not spend spoken time listing every version.')
h('Explain what you built and pass the story forward')
label('Delivery','Increase energy slightly. This is the transition from the problem to the working prototype. End clearly, then hold your gaze for a second.')
speech('That led us to a streaming prototype with repeatable tests, a dashboard and an edge runtime. My teammate will now show the signal path and the live comparison.')
label('Action','Stay facing the camera. Finish the sentence, remain still and hold for one second. There is no physical turn toward Speaker 2 because the recordings are in separate locations.')
label('Edit','Cut to Speaker 2 after “live comparison”. Start with the speaker visible beside the laptop, then move to the dashboard. Both people look into their own camera. A straight cut connects the separate locations.')
h('How Speaker 1 should feel across the opening')
p('Start with concern for the missed instruction. Move into curiosity about the first idea. Explain the constraints with calm precision, then show confidence in what you have actually built. The emotion comes from the meaning of the words. You do not need a prescribed blink, eyebrow movement or gesture on every line.')
h('Optional fuller take for a longer edit')
p('Record the following paragraph separately. It adds about 15 to 20 seconds and belongs after the microphone lesson. Include it only if the submission allows a longer film.')
speech('That is also why a good laboratory score could not be our final answer. We needed to know whether the voice survived, whether difficult clips still failed, and whether the runtime could keep delivering audio. Each test gave us a more specific problem to fix.')

page('Speaker 2 technical explanation and live demonstration')
h('Explain the signal path')
label('Action','Stand or sit naturally beside the laptop. Point once at the two input traces. After that, let the screen recording carry the explanation.')
speech('I am [Name 2], also from Team@. Here, the primary microphone captures voice plus noise; the reference captures the surroundings. A causal dual-input deep-filter model processes both through stateful ONNX inference. These traces show the inputs and output. We are demonstrating separate laptop audio devices; synchronized capture is our next hardware step.')
label('Screen','Show Primary microphone -> dual-input model -> output, with the reference microphone entering the model separately. Label the current setup SEPARATE WINDOWS AUDIO DEVICES. Do not name GTCRN as the current architecture.')
h('Speak only briefly during the comparison')
speech('Let us hear the difference. First, bypass.')
label('After the bypass command','Say “Now, enhancement”, switch the mode, and repeat the command. Introduce each mode immediately before its corresponding audio, rather than announcing both switches before either happens.')
label('Then say','Hold position. Left flank clear. Move on my mark.')
p('Say the command once in bypass, switch to enhancement, then repeat it at the same level and mouth-to-microphone distance. Allow the viewer to hear both without narration covering them. Aim for six to eight seconds of command audio in each mode, plus the transition.')
h('Actions during the demonstration')
bullets(['Keep the phone noise source at a fixed distance and volume for both modes.','Keep microphone gains and headphone volume fixed. Change only the enhancement control being demonstrated.','Record the dashboard and direct output audio continuously through the switch. Keep the mode label visible.','If controlled reference mixing is active, display CONTROLLED REFERENCE MIX on screen and describe the comparison as a controlled demonstration.','Use a live clip that actually shows an audible improvement. If it fails during the take, investigate and record again; keep the evidence report from the successful session.'])
h('What the viewer should see')
p('Show independent activity on the voice and environment traces, the selected mode, and actual output activity. In a small readable corner, keep inference time and runtime faults visible. Do not fill the frame with all dashboard numbers. The audible comparison is the focus.')

page('Speaker 2 evidence and Speaker 1 close')
h('Measured results and the Pi')
speech('To check beyond this example, we ran repeatable audits. V15 passed the broad fifty-clip gate; harder military clips still missed reliability targets. Our earlier Pi 5 benchmark averaged 5.33 milliseconds per sixteen-millisecond frame. That supports edge feasibility, while this checkpoint still needs its own Pi verification.')
label('Overlay','V15 BROAD AUDIT / 50 CLIPS: SNR 30.48 dB, STOI 0.938, PESQ 3.94. V15 MILITARY AUDIT: reliability gate not passed. EARLIER PI 5 BENCHMARK: mean 5.33 ms, frame 16 ms. Do not place the earlier timing beside the v15 results in a way that implies they came from the same checkpoint.')
label('Pi footage','Film the real board, its power connection and a readable terminal result. If you rerun the current v15 checkpoint on the Pi successfully, replace the earlier benchmark wording and overlays with that newly verified report. A powered board alone is not evidence that this checkpoint ran on it.')
h('Speaker 1 returns')
label('Framing','Return to Speaker 1 in the same location and camera position as the opening. No hardware needs to be visible in this location. Use actual build footage over the first sentence if useful.')
label('Delivery','Calm confidence. Pause after the first sentence. Treat the next hardware step as a concrete plan. Lower your hands and slow down for the closing question.')
speech('Those results give Team@ a clear next step: synchronized capture, target-headset recordings and physical latency testing. We want VoxShield to become a practical local layer for existing communication equipment. We started with a missed command. Our next tests will ask whether the listener can still understand it when the noise rises. We are Team@. This is VoxShield.')
label('Reaction','Finish with steady eye contact and a natural expression. Hold still for one second. A slight smile afterward is fine; there is no need to perform triumph.')
label('Edit','Speaker 2\'s final Pi shot cuts to Speaker 1 already framed in the opening location. Show NEXT: synchronized capture / headset recordings / physical latency. On “missed command”, return to HOLD POSITION from the opening. End with Team@, VoxShield, PS 26052 and the QR code for four seconds. The opening and closing now belong to the same story.')
h('Optional fuller close')
p('For a longer version, insert this after the first sentence. Record it as a separate take; it adds about 12 to 15 seconds.')
speech('The value of the project is that we can follow the whole path, from captured sound to the listener, and find where a failure happens. That gives us a way to improve both the model and the hardware instead of guessing.')

page('Recording and editing directions')
h('Rehearse for natural delivery')
bullets(['Read each paragraph aloud once without gestures. Mark where you naturally breathe.','Tell the same idea to your teammate without looking at the script. Keep that conversational rhythm when returning to the exact wording.','Use pauses after ideas, not after every caption. One purposeful hand movement per paragraph is usually enough.','Record two takes: a relaxed take and a slightly tighter take. Leave two seconds of silence at the beginning and end of each.','Check one take with sound muted for nervous movement, then listen without watching to judge clarity.'])
h('Capture the two locations consistently')
p('Record horizontally at 1080p or above. Put the camera at eye level and look at the lens, not your own preview. Use a quiet room and soft light facing the speaker. Keep each person at a similar size in frame. Match subtitle font, lower thirds and audio loudness across both locations. The backgrounds can differ naturally.')
h('Audio and animation')
p('Capture clean narration. Add the two-second opening static in the editor at a comfortable level. Use a quiet music bed only during the introduction and closing; remove it completely during the A/B listening section. Use simple animated arrows and captions to explain ideas. Record the demo output directly so camera audio, room acoustics and headphone leakage do not obscure the comparison.')
h('If the edit runs long')
bullets(['Remove both optional paragraphs first.','Shorten the early journey to: “Real microphone testing showed us that placement, device processing and synchronization matter as much as the model.”','Move detailed metric values to the screen while retaining the spoken broad-pass and military-failure status.','Keep enough A/B audio to hear the difference and retain the statement that the Pi number is from an earlier benchmark.','Do not speed the entire film up to fit. Time the actual rehearsal; the displayed ranges are targets, not guaranteed speech durations.'])
h('Evidence linked by the final QR')
p('Link a mobile-friendly page with the submitted video, an uncut A/B recording, current architecture, both v15 audit summaries, the Pi report with its exact model identity, a short list of limitations and the next hardware steps. Include downloadable reports and team contact details. Test the QR from another phone before export.')
h('Final review')
p('Watch the film once as a judge who has never met the team. Within the opening, the missed-command problem should be clear. By the middle, the signal path and audible comparison should be understandable. By the end, the viewer should know what exists today and what you will build next. Check the portal duration limit before submitting.')

d.save(OUT)
print(OUT)
